-- ============================================
-- LUMA — Thème 16 : MOYEN 2/3 x4 — Obtenir son Tax File Number
-- ============================================


update scenarios set content = '{"characters": {"agent": "l''agent des impôts (téléphone)"}, "start_node": "n1", "nodes": {"n1": {"speaker": "agent", "text": "So you''re on a working holiday visa? You''ll need a Tax File Number before you start any job.", "text_fr": "Donc vous êtes en visa vacances-travail ? Il vous faut un numéro fiscal avant de commencer tout emploi.", "choices": [{"text": "How do I apply for that?", "text_fr": "Comment je fais la demande pour ça ?", "next": "n2"}, {"text": "I''ve heard it''s important — what happens if I work without one?", "text_fr": "J''ai entendu dire que c''est important — qu''est-ce qui se passe si je travaille sans ?", "next": "n2b"}]}, "n2": {"speaker": "agent", "text": "You can apply online through our website, it takes about 10 minutes.", "text_fr": "Vous pouvez faire la demande en ligne sur notre site, ça prend environ 10 minutes.", "choices": [{"text": "That sounds simple enough. What information do I need to have ready?", "text_fr": "Ça a l''air assez simple. Quelles informations je dois avoir prêtes ?", "next": "n3"}]}, "n2b": {"speaker": "agent", "text": "Without one, you''ll be taxed at the highest rate, nearly half your income.", "text_fr": "Sans ça, vous serez taxé au taux le plus élevé, presque la moitié de votre revenu.", "choices": [{"text": "That''s a big incentive to apply right away then!", "text_fr": "C''est une grande motivation pour faire la demande tout de suite alors !", "next": "n3"}]}, "n3": {"speaker": "agent", "text": "Just your passport details and visa information, plus an Australian address.", "text_fr": "Juste vos informations de passeport et de visa, plus une adresse australienne.", "choices": [{"text": "I have all of that ready. Can I apply from my phone?", "text_fr": "J''ai tout ça de prêt. Je peux faire la demande depuis mon téléphone ?", "next": "n4"}]}, "n4": {"speaker": "agent", "text": "Yes, the website works fine on mobile too.", "text_fr": "Oui, le site fonctionne bien sur mobile aussi.", "choices": [{"text": "Perfect, I''ll do that right after this call then.", "text_fr": "Parfait, je vais faire ça juste après cet appel alors.", "next": "n5"}]}, "n5": {"speaker": "agent", "text": "Usually 10 to 28 business days by mail, so apply as early as possible.", "text_fr": "Généralement 10 à 28 jours ouvrés par courrier, donc faites-en la demande au plus tôt.", "choices": [{"text": "That''s good to know, I''ll get started immediately.", "text_fr": "C''est bon à savoir, je vais commencer immédiatement.", "next": "n6"}, {"text": "Is there any way to speed up the process if I need to start work sooner?", "text_fr": "Il y a un moyen d''accélérer le processus si je dois commencer à travailler plus tôt ?", "next": "n6"}]}, "n6": {"speaker": "agent", "text": "Unfortunately not, but you can start work while it''s processing, just note the interim number.", "text_fr": "Malheureusement non, mais vous pouvez commencer à travailler pendant le traitement, notez juste le numéro provisoire.", "choices": [{"text": "That''s helpful, thank you for explaining the whole process.", "text_fr": "C''est utile, merci d''avoir expliqué tout le processus.", "next": "n7"}]}, "n7": {"speaker": "agent", "text": "No worries at all, this is really common for working holiday visa holders.", "text_fr": "Aucun souci, c''est vraiment courant pour les détenteurs de visa vacances-travail.", "choices": [{"text": "Thank you, I''ll apply today then.", "text_fr": "Merci, je vais faire la demande aujourd''hui alors.", "next": "end_applied"}]}, "end_applied": {"speaker": "agent", "text": "Perfect, good luck with your working holiday!", "text_fr": "Parfait, bonne chance pour votre séjour vacances-travail !", "end": true, "ending_label": "Démarche administrative comprise et lancée 📋🇦🇺"}}}'::jsonb, is_playable = true
where title = 'Obtenir son Tax File Number'
  and theme_id = (select id from scenario_themes where position = 16 and language_id = (select id from languages where code = 'en'));
